   551      case region_list:   kputs(" genomic region", &str); break;
   552      default: break;
   553      }
   554
   555      if (format->compression == no_compression)
   556          switch (format->format) {
   557          case text_format:
   558          case sam:
   559          case crai:
   560          case vcf:
   561          case bed:
   562          case fai_format:
   563          case fqi_format:
   564          case fasta_format:
   565          case fastq_format:
   566          case htsget:
   567              kputs(" text", &str);
   568              break;
   569
   570          case empty_format:
   571              break;
   572
   573          default:
   574              kputs(" data", &str);
   575              break;
   576          }
   577      else
   578          kputs(" data", &str);
   579
   580      return ks_release(&str);
   581  }
